import ctypes

class MemoryManager:
    def __init__(self, total_size=1024 * 1024):  # 1 MB default
        self.memory = ctypes.create_string_buffer(total_size)
        self.used = [False] * (total_size // 4)  # Assuming 4-byte alignment
        self.total_size = total_size

    def allocate(self, size):
        # Find a contiguous block of memory of the required size
        for i in range(len(self.used) - (size // 4) + 1):
            if not any(self.used[i:i + (size // 4)]):
                # Mark the block as used
                for j in range(i, i + (size // 4)):
                    self.used[j] = True
                # Return pointer to the start of the block
                return ctypes.addressof(self.memory) + i * 4
        # Allocation failed
        return None

    def deallocate(self, ptr):
        # Convert pointer to index
        index = (ptr - ctypes.addressof(self.memory)) // 4
        if 0 <= index < len(self.used):
            for i in range(index, index + (self.used[index] * 4)):
                if i < len(self.used):
                    self.used[i] = False

