class MemoryManager:
    def __init__(self, size):
        self.memory = [None] * size
        self.size = size
        self.used = [False] * size

    def allocate(self, block_size):
        if block_size > self.size:
            raise MemoryError("Requested block size exceeds available memory")

        for i in range(self.size - block_size + 1):
            if all(not self.used[j] for j in range(i, i + block_size)):
                for j in range(i, i + block_size):
                    self.used[j] = True
                return i
        raise MemoryError("Not enough contiguous memory available")

    def deallocate(self, start_index, block_size):
        for i in range(start_index, start_index + block_size):
            if i >= self.size or i < 0:
                raise IndexError("Invalid memory index")
            self.used[i] = False

    def set_status(self, index, status):
        if index < 0 or index >= self.size:
            raise IndexError("Invalid memory index")
        self.memory[index] = status

