import ctypes

class Person:
    def __init__(self):
        self.name = ""
        self.age = 0
        self.status = 0

def allocate_memory(size):
    return ctypes.c_char_p(ctypes.pythonapi.malloc(size))

def free_memory(ptr):
    ctypes.pythonapi.free(ptr)

def main():
    for _ in range(1000):
        # Bellek bloğu tahsis et (Person sınıfı boyutu)
        person_ptr = allocate_memory(ctypes.sizeof(Person))

        # Bellek bloğuna bir kişi nesnesi yaz
        person = ctypes.cast(person_ptr, ctypes.POINTER(Person)).contents
        person.name = ""
        person.age = 0
        person.status = 0

        # Belleği serbest bırak
        free_memory(person_ptr)

if __name__ == "__main__":
    main()
